+  slug: string;
+  base_time: string;
+  detail_state: CaseState;
+  peak_tier: RainTier | null;
+  peak_valid_time: string | null;
+  slots: CaseSlot[];
+  verification: CaseVerification[] | null;
+};
+
+export type RainCase = {
